27	int aws_byte_buf_init(struct aws_allocator *allocator, struct aws_byte_buf *buf, size_t capacity) {
28	    buf->buffer = (uint8_t *)aws_mem_acquire(allocator, capacity);
29	    if (!buf->buffer) {
30	        return AWS_OP_ERR;
31	    }
32	    buf->len = 0;
33	    buf->capacity = capacity;
34	    buf->allocator = allocator;
35	    return AWS_OP_SUCCESS;
36	}
37	
38	void aws_byte_buf_clean_up(struct aws_byte_buf *buf) {
39	    if (buf->allocator && buf->buffer) {
40	        aws_mem_release(buf->allocator, (void *)buf->buffer);
41	    }
42	    buf->allocator = NULL;
43	    buf->buffer = NULL;
44	    buf->len = 0;
45	    buf->capacity = 0;
46	}
47	
48	void aws_byte_buf_secure_zero(struct aws_byte_buf *buf) {
49	    if (buf->buffer) {
50	        aws_secure_zero(buf->buffer, buf->capacity);
51	    }
52	    buf->len = 0;
53	}
54	
55	void aws_byte_buf_clean_up_secure(struct aws_byte_buf *buf) {
56	    aws_byte_buf_secure_zero(buf);
57	    aws_byte_buf_clean_up(buf);
58	}
59	
60	bool aws_byte_buf_eq(const struct aws_byte_buf *a, const struct aws_byte_buf *b) {
61	    if (!a || !b) {
62	        return (a == b);
63	    }
64	
65	    if (a->len != b->len) {
66	        return false;
67	    }
68	
69	    if (!a->buffer || !b->buffer) {
70	        return (a->buffer == b->buffer);
71	    }
72	
73	    return !memcmp(a->buffer, b->buffer, a->len);
74	}
75	
76	int aws_byte_buf_init_copy(struct aws_allocator *allocator, struct aws_byte_buf *dest, const struct aws_byte_buf *src) {
77	    assert(allocator);
78	    assert(dest);
79	    assert(src);
80	
81	    dest->len = 0;
82	    dest->capacity = 0;
83	    dest->allocator = NULL;
84	    if (src->buffer == NULL) {
85	        dest->buffer = NULL;
86	        return AWS_OP_SUCCESS;
87	    }
88	
89	    dest->buffer = (uint8_t *)aws_mem_acquire(allocator, sizeof(uint8_t) * src->len);
90	    if (dest->buffer == NULL) {
91	        return AWS_OP_ERR;
92	    }
93	
94	    dest->len = src->len;
95	    dest->capacity = src->len;
96	    dest->allocator = allocator;
97	    memcpy(dest->buffer, src->buffer, src->len);
98	    return AWS_OP_SUCCESS;
99	}
100	
101	bool aws_byte_buf_next_split(const struct aws_byte_buf *input_str, char split_on, struct aws_byte_cursor *substr) {
102	
103	    bool first_run = false;
104	    if (!substr->ptr) {
105	        first_run = true;
106	        substr->ptr = input_str->buffer;
107	        substr->len = 0;
108	    }
109	
110	    if (substr->ptr > input_str->buffer + input_str->len) {
111	        /* This will hit if the last substring returned was an empty string after terminating split_on. */
112	        AWS_ZERO_STRUCT(*substr);
113	        return false;
114	    }
115	
116	    /* Calculate first byte to search. */
117	    substr->ptr += substr->len;
118	    /* Remaining bytes is the number we started with minus the number of bytes already read. */
119	    substr->len = input_str->len - (substr->ptr - input_str->buffer);
120	
121	    if (!first_run && substr->len == 0) {
122	        /* This will hit if the string doesn't end with split_on but we're done. */
123	        AWS_ZERO_STRUCT(*substr);
124	        return false;
125	    }
126	
127	    if (!first_run && *substr->ptr == split_on) {
128	        /* If not first rodeo and the character after substr is split_on, skip. */
129	        ++substr->ptr;
130	        --substr->len;
131	
132	        if (substr->len == 0) {
133	            /* If split character was last in the string, return empty substr. */
134	            return true;
135	        }
136	    }
137	
138	    uint8_t *new_location = memchr(substr->ptr, split_on, substr->len);
139	    if (new_location) {
140	
141	        /* Character found, update string length. */
142	        substr->len = new_location - substr->ptr;
143	    }
144	
145	    return true;
146	}
147	
148	int aws_byte_buf_split_on_char_n(
149	    const struct aws_byte_buf *input_str,
150	    char split_on,
151	    struct aws_array_list *output,
152	    size_t n) {
153	    assert(input_str && input_str->buffer);
154	    assert(output);
155	    assert(output->item_size >= sizeof(struct aws_byte_cursor));
156	
157	    size_t max_splits = n > 0 ? n : SIZE_MAX;
158	    size_t split_count = 0;
159	
160	    struct aws_byte_cursor substr;
161	    AWS_ZERO_STRUCT(substr);
162	
163	    /* Until we run out of substrs or hit the max split count, keep iterating and pushing into the array list. */
164	    while (split_count <= max_splits && aws_byte_buf_next_split(input_str, split_on, &substr)) {
165	
166	        if (split_count == max_splits) {
167	            /* If this is the last split, take the rest of the string. */
168	            substr.len = input_str->len - (substr.ptr - input_str->buffer);
169	        }
170	
171	        if (AWS_UNLIKELY(aws_array_list_push_back(output, (const void *)&substr))) {
172	            return AWS_OP_ERR;
173	        }
174	        ++split_count;
175	    }
176	
177	    return AWS_OP_SUCCESS;
178	}
179	
180	int aws_byte_buf_split_on_char(const struct aws_byte_buf *input_str, char split_on, struct aws_array_list *output) {
181	    return aws_byte_buf_split_on_char_n(input_str, split_on, output, 0);
182	}
183	
184	int aws_byte_buf_cat(struct aws_byte_buf *dest, size_t number_of_args, ...) {
185	    assert(dest);
186	
187	    va_list ap;
188	    va_start(ap, number_of_args);
189	
190	    for (size_t i = 0; i < number_of_args; ++i) {
191	        struct aws_byte_buf *buffer = va_arg(ap, struct aws_byte_buf *);
192	        struct aws_byte_cursor cursor = aws_byte_cursor_from_buf(buffer);
193	
194	        if (aws_byte_buf_append(dest, &cursor)) {
195	            va_end(ap);
196	            return AWS_OP_ERR;
197	        }
198	    }
199	
200	    va_end(ap);
201	    return AWS_OP_SUCCESS;
202	}
203	
204	bool aws_byte_cursor_eq(const struct aws_byte_cursor *a, const struct aws_byte_cursor *b) {
205	
206	    if (!a || !b) {
207	        return (a == b);
208	    }
209	
210	    if (a->len != b->len) {
211	        return false;
212	    }
213	
214	    if (!a->ptr || !b->ptr) {
215	        return (a->ptr == b->ptr);
216	    }
217	
218	    return !memcmp(a->ptr, b->ptr, a->len);
219	}
220	
221	bool aws_byte_cursor_eq_byte_buf(const struct aws_byte_cursor *a, const struct aws_byte_buf *b) {
222	
223	    if (!a || !b) {
224	        return ((void *)a == (void *)b);
225	    }
226	
227	    if (a->len != b->len) {
228	        return false;
229	    }
230	
231	    if (!a->ptr || !b->buffer) {
232	        return (a->ptr == b->buffer);
233	    }
234	
235	    return !memcmp(a->ptr, b->buffer, a->len);
236	}
237	
238	int aws_byte_buf_append(struct aws_byte_buf *to, struct aws_byte_cursor *from) {
239	    assert(from->ptr);
240	    assert(to->buffer);
241	
242	    if (to->capacity - to->len < from->len) {
243	        return aws_raise_error(AWS_ERROR_DEST_COPY_TOO_SMALL);
244	    }
245	
246	    memcpy(to->buffer + to->len, from->ptr, from->len);
247	    to->len += from->len;
248	    return AWS_OP_SUCCESS;
249	}
