102	
103	    if (AWS_UNLIKELY(output->capacity < encoded_len)) {
104	        return aws_raise_error(AWS_ERROR_SHORT_BUFFER);
105	    }
106	
107	    size_t written = 0;
108	    for (size_t i = 0; i < to_encode->len; ++i) {
